import { describe, it, expect } from 'vitest';
import {
  шумоваяРеплика, завестиСчётчик, шаг, прослушанВесь, перенестиПоВремени,
  type Счётчик, type Реплика,
} from '../subtitle-counter';

// Разбор 2026-10-05 (решения владельца): «прослушан» — по СУБТИТРАМ, а не по времени ролика;
// шумовые реплики ([Music] и т. п. — маркеры демона) в подсчёте не участвуют; при смене
// дорожки посреди ролика «услышано» переносится ПО ВРЕМЕНИ.

const р = (start: number, end: number, text: string): Реплика => ({ start, end, text });
const завести = (реплики: Реплика[]) => завестиСчётчик({ puzzleID: 'p1', ключ: 'k', реплики });
const ход = (c: Счётчик, до: number, от = c.было ?? 0): Счётчик => {
  let x = c;
  for (let t = от; t <= до + 1e-9; t += 0.5) x = шаг(x, { время: t, сдвиг: 0, идётПеремотка: false, ставка: 1 });
  return x;
};

describe('шумоваяРеплика', () => {
  it.each([
    ['[Music]', true], ['[музыка]', true], ['♪ ♪', true], ['music ♪', true], ['[Applause]', true],
    ['(laughter)', true], ['[Music] [Applause]', true], ['', true], ['...', true], ['foreign', true],
    ['[Music] you', false], ['I love music', false], ['(laughs) I know', false], ['Hello there', false],
  ])('%j → %s', (text, шум) => {
    expect(шумоваяРеплика(text)).toBe(шум);
  });
});

describe('прослушанВесь', () => {
  const R = [р(0, 2, 'Hello there'), р(2, 4, 'I never said that'), р(4, 9, '[Music]')];

  it('⚠️ все нешумовые услышаны — прослушан, хвост из музыки слушать не нужно', () => {
    const c = ход(завести(R), 4.5);
    expect(c.услышано[2]).toBe(0);
    expect(прослушанВесь(c)).toBe(true);
  });

  it('пропущенная перемоткой реплика — не прослушан', () => {
    let c = ход(завести(R), 2.5);
    c = шаг(c, { время: 4.5, сдвиг: 0, идётПеремотка: true, ставка: 1 });   // мимо реплики 1
    expect(прослушанВесь(c)).toBe(false);
  });

  it('нешумовых реплик нет — по субтитрам не решаем (false; решает конец ролика)', () => {
    const c = ход(завести([р(0, 5, '[Music]')]), 6);
    expect(прослушанВесь(c)).toBe(false);
  });
});

describe('проигранные отрезки и перенос по времени', () => {
  const старая = [р(0, 2, 'hello there'), р(2, 4, 'never said'), р(4, 6, 'wait for me')];

  it('счётчик копит проигранные отрезки, перемотка разрывает их', () => {
    let c = ход(завести(старая), 3);
    c = шаг(c, { время: 5, сдвиг: 0, идётПеремотка: true, ставка: 1 });
    c = ход(c, 6, 5);
    expect(c.проиграно).toEqual([[0, 3], [5, 6]]);
  });

  it('⚠️ новая дорожка (другой текст и нарезка): услышано по времени, отчёт остаётся полным', () => {
    const c = ход(завести(старая), 4.5);   // проиграно [0, 4.5]
    const новая = [р(0.1, 1.9, 'Hello there.'), р(2.1, 3.9, 'I never said that.'), р(4.2, 5.8, 'Wait for me!')];
    const п = перенестиПоВремени(c, { puzzleID: 'p1', ключ: 'k2', реплики: новая });
    expect(п.услышано).toEqual([1, 1, 0]);
    expect(п.полный).toBe(true);
    expect(п.снимок.реплики).toBe(новая);
    expect(п.проиграно).toEqual(c.проиграно);
  });

  it('реплика новой дорожки там, где у старой было пусто, но звук проигран, — услышана', () => {
    const c = ход(завести([р(0, 1, 'hi'), р(5, 6, 'bye')]), 6.5);
    const п = перенестиПоВремени(c, { puzzleID: 'p1', ключ: 'k2', реплики: [р(2, 4, 'found by whisper')] });
    expect(п.услышано).toEqual([1]);
  });

  it('частично проигранная реплика — не услышана', () => {
    const c = ход(завести(старая), 3);
    const п = перенестиПоВремени(c, { puzzleID: 'p1', ключ: 'k2', реплики: [р(2, 4.5, 'never said that')] });
    expect(п.услышано).toEqual([0]);
  });
});

describe('аудит 2026-10-05', () => {
  it('MED-3: перенос согласован с правилом шага — вошёл в середину и прошёл конец = услышана', () => {
    let c = завести([р(0, 1, 'a b'), р(2, 4, 'never said')]);
    c = шаг(c, { время: 3, сдвиг: 0, идётПеремотка: true, ставка: 1 });   // прыжок в середину
    c = ход(c, 6, 3);
    expect(c.услышано[1]).toBe(1);   // правило шага
    const п = перенестиПоВремени(c, { puzzleID: 'p1', ключ: 'k2', реплики: [р(2.1, 3.9, 'I never said that')] });
    expect(п.услышано).toEqual([1]);
  });

  it.each(['[Cheering]', 'cheering', 'snort', 'clears'])('маркеры демона полностью: %s — шум', (t) => {
    expect(шумоваяРеплика(t)).toBe(true);
  });
});
